<?php
namespace Tests\Feature;
use App\Models\Employee; use App\Models\Tenant; use App\Models\User; use App\Services\EmployeeDocumentService; use Illuminate\Http\UploadedFile; use Illuminate\Support\Facades\Storage; use Illuminate\Support\Str; use Tests\TestCase;
class EmployeeDocumentTest extends TestCase { public function test_private_document_is_tenant_scoped_and_checksummed():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Docs '.Str::random(4)]);try{tenancy()->initialize($tenant);Storage::fake('local');$u=User::create(['name'=>'HR','email'=>Str::uuid().'@example.test','password'=>'secret123','role'=>'hr']);$e=Employee::create(['name'=>'E','national_id'=>'DOC-'.Str::uuid(),'hire_date'=>'2026-01-01','salary'=>'400.000','status'=>'active']);$file=UploadedFile::fake()->createWithContent('contract.pdf','%PDF-1.4 test');$d=app(EmployeeDocumentService::class)->store($e,$file,'contract',null,$u->id);$this->assertStringContainsString('tenants/'.$tenant->id.'/employees/'.$e->id,$d->storage_path);Storage::disk('local')->assertExists($d->storage_path);$this->assertSame(64,strlen($d->sha256));}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
